import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'signup_screen.dart';import 'auth_provider.dart';import 'biometric_setup_screen.dart';import '../data/biometric_service.dart';import '../data/decoy_service.dart';import '../../../core/presentation/main_screen.dart';import '../../../features/stealth/presentation/hidden_inbox_screen.dart';import '../../../core/presentation/widgets/glass_container.dart';final decoyServiceProvider = Provider<DecoyService>((ref) {  return DecoyService();});class LoginScreen extends ConsumerStatefulWidget {  const LoginScreen({super.key});  @override  ConsumerState<LoginScreen> createState() => _LoginScreenState();}class _LoginScreenState extends ConsumerState<LoginScreen> {  final _formKey = GlobalKey<FormState>();  final _usernameController = TextEditingController();  final _passwordController = TextEditingController();  bool _isAuthenticating = false;  bool _showBiometricOption = false;  @override  void initState() {    super.initState();    _checkBiometricOnStart();  }  @override  void dispose() {    _usernameController.dispose();    _passwordController.dispose();    super.dispose();  }  Future<void> _checkBiometricOnStart() async {    final biometricService = ref.read(biometricServiceProvider);    final isEnabled = await biometricService.isBiometricEnabled();    if (isEnabled) {      setState(() => _showBiometricOption = true);    }  }  Future<void> _authenticateWithBiometric() async {    setState(() => _isAuthenticating = true);    try {      final biometricService = ref.read(biometricServiceProvider);      final success = await biometricService.authenticate(        reason: 'Authenticate to access Catus Chat',      );      if (success && mounted) {        Navigator.pushReplacement(          context,          MaterialPageRoute(builder: (context) => const MainScreen()),        );      }    } finally {      if (mounted) {        setState(() => _isAuthenticating = false);      }    }  }  @override  Widget build(BuildContext context) {    final authState = ref.watch(authStateProvider);    final decoyService = ref.read(decoyServiceProvider);    return Scaffold(      body: Container(        decoration: const BoxDecoration(          gradient: LinearGradient(            begin: Alignment.topLeft,            end: Alignment.bottomRight,            colors: [Color(0xFF0D47A1), Color(0xFF000000)],          ),        ),        child: SafeArea(          child: Center(            child: SingleChildScrollView(              padding: const EdgeInsets.all(24.0),              child: Form(                key: _formKey,                child: Column(                  mainAxisAlignment: MainAxisAlignment.center,                  crossAxisAlignment: CrossAxisAlignment.stretch,                  children: [                    const Icon(Icons.lock_person_sharp,                        size: 80, color: Colors.blueAccent),                    const SizedBox(height: 24),                    const Text(                      '#PROJ16',                      textAlign: TextAlign.center,                      style: TextStyle(                        fontSize: 32,                        fontWeight: FontWeight.bold,                        color: Colors.white,                        letterSpacing: 2,                      ),                    ),                    const Text(                      'Secure Cloud & Communication',                      textAlign: TextAlign.center,                      style: TextStyle(color: Colors.blueGrey, fontSize: 14),                    ),                    const SizedBox(height: 48),                    if (_showBiometricOption && !_isAuthenticating) ...[                      GlassContainer(                        opacity: 0.15,                        child: InkWell(                          onTap: _authenticateWithBiometric,                          borderRadius: BorderRadius.circular(12),                          child: Padding(                            padding: const EdgeInsets.symmetric(                                vertical: 16, horizontal: 12),                            child: Row(                              mainAxisAlignment: MainAxisAlignment.center,                              children: [                                const Icon(Icons.fingerprint,                                    color: Colors.blueAccent, size: 28),                                const SizedBox(width: 12),                                const Text(                                  'Unlock with Biometrics',                                  style: TextStyle(                                      color: Colors.white,                                      fontSize: 16,                                      fontWeight: FontWeight.w500),                                ),                              ],                            ),                          ),                        ),                      ),                      const SizedBox(height: 16),                      const Text(                        '— or —',                        textAlign: TextAlign.center,                        style: TextStyle(color: Colors.white54, fontSize: 12),                      ),                      const SizedBox(height: 16),                    ],                    if (_isAuthenticating) ...[                      const Center(                        child: Column(                          children: [                            CircularProgressIndicator(color: Colors.blueAccent),                            SizedBox(height: 12),                            Text('Authenticating...',                                style: TextStyle(color: Colors.white70)),                          ],                        ),                      ),                      const SizedBox(height: 24),                    ],                    TextFormField(                      controller: _usernameController,                      style: const TextStyle(color: Colors.white),                      decoration: InputDecoration(                        filled: true,                        fillColor: Colors.white.withOpacity(0.1),                        hintText: 'Username',                        hintStyle: const TextStyle(color: Colors.white54),                        prefixIcon:                            const Icon(Icons.person, color: Colors.white70),                        border: OutlineInputBorder(                          borderRadius: BorderRadius.circular(12),                          borderSide: BorderSide.none,                        ),                      ),                      validator: (value) =>                          value!.isEmpty ? 'Enter username' : null,                    ),                    const SizedBox(height: 16),                    TextFormField(                      controller: _passwordController,                      obscureText: true,                      style: const TextStyle(color: Colors.white),                      decoration: InputDecoration(                        filled: true,                        fillColor: Colors.white.withOpacity(0.1),                        hintText: 'Password',                        hintStyle: const TextStyle(color: Colors.white54),                        prefixIcon:                            const Icon(Icons.lock, color: Colors.white70),                        border: OutlineInputBorder(                          borderRadius: BorderRadius.circular(12),                          borderSide: BorderSide.none,                        ),                      ),                      validator: (value) =>                          value!.length < 6 ? 'Password too short' : null,                    ),                    const SizedBox(height: 24),                    authState.when(                      data: (success) {                        if (success) {                          WidgetsBinding.instance.addPostFrameCallback((_) {                            _handleSuccessfulLogin();                          });                        }                        return ElevatedButton(                          onPressed: () => _handleLogin(decoyService),                          style: ElevatedButton.styleFrom(                            backgroundColor: Colors.blueAccent,                            foregroundColor: Colors.white,                            padding: const EdgeInsets.symmetric(vertical: 16),                            shape: RoundedRectangleBorder(                              borderRadius: BorderRadius.circular(12),                            ),                            elevation: 5,                          ),                          child: const Text('Login',                              style: TextStyle(                                  fontSize: 16, fontWeight: FontWeight.bold)),                        );                      },                      loading: () => const Center(                          child: CircularProgressIndicator(                              color: Colors.blueAccent)),                      error: (err, stack) => Column(                        children: [                          Text('Error: $err',                              style: const TextStyle(color: Colors.redAccent)),                          const SizedBox(height: 8),                          ElevatedButton(                            onPressed: () => _handleLogin(decoyService),                            child: const Text('Retry'),                          ),                        ],                      ),                    ),                    const SizedBox(height: 16),                    TextButton(                      onPressed: () {                        Navigator.push(                          context,                          MaterialPageRoute(                              builder: (context) => const SignupScreen()),                        );                      },                      child: const Text('Don\'t have an account? Sign Up',                          style: TextStyle(color: Colors.white70)),                    ),                  ],                ),              ),            ),          ),        ),      ),    );  }  Future<void> _handleLogin(DecoyService decoyService) async {    if (!_formKey.currentState!.validate()) return;    await decoyService.initialize();    final password = _passwordController.text;    final result = await decoyService.authenticate(password);    if (!mounted) return;    switch (result) {      case AuthResult.decoy:        Navigator.pushReplacement(          context,          MaterialPageRoute(builder: (context) => const HiddenInboxScreen()),        );        break;      case AuthResult.real:        ref.read(authStateProvider.notifier).login(              _usernameController.text,              _passwordController.text,            );        break;      case AuthResult.failed:        ScaffoldMessenger.of(context).showSnackBar(          const SnackBar(            content: Text('Invalid credentials'),            backgroundColor: Colors.redAccent,          ),        );        break;    }  }  void _handleSuccessfulLogin() {    Navigator.pushReplacement(      context,      MaterialPageRoute(builder: (context) => const MainScreen()),    );  }}